#[verus::spec]
fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>> {
    // Precondition: n and m must be greater than 0
    // Requires: n > 0 && m > 0
    // Ensures: The returned matrix has dimensions n x m
    // Ensures: For all i in 0..n and j in 0..m, if j <= (i as i32 + k), then matrix[i][j] == 1.0, else matrix[i][j] == 0.0
    // Decreases: n, m
    let mut matrix = vec![vec![0.0; m]; n]; // Initialize an n-by-m matrix with 0.0

    // Invariant: 0 <= i <= n && 0 <= j <= m
    for i in 0..n {
        for j in 0..m {
            // Invariant: j <= (i as i32 + k) implies matrix[i][j] == 1.0
            if j <= (i as i32 + k) {
                matrix[i][j] = 1.0; // Set the value to 1.0 if the condition is met
            }
        }
    }

    matrix // Return the constructed matrix
}

